import DashboardLayout from "@/components/DashboardLayout";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import { trpc } from "@/lib/trpc";
import { toast } from "sonner";
import { Area, AreaChart, ResponsiveContainer, Tooltip, XAxis } from "recharts";
import { ArrowUpRight, CalendarDays, Check, ChevronRight, Copy, CreditCard, ExternalLink, FileText, Mail, Package, Plus, Send, Users } from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { useLocation } from "wouter";
import { useAuth } from "@/_core/hooks/useAuth";
import { LinksWorkspace, MediaLibrary, PagesWorkspace } from "./CreatorContentStudio";
import StorefrontBuilder from "./StorefrontBuilder";

const money = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });
const dateText = (value: Date | string) => new Date(value).toLocaleDateString(undefined, { month: "short", day: "numeric" });
const fieldClass = "h-10 border-slate-200 bg-white text-sm focus-visible:ring-slate-950";

function PageHeading({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description: string; action?: React.ReactNode }) {
  return <div className="mb-8 flex flex-col gap-5 md:flex-row md:items-end md:justify-between"><div>{eyebrow ? <p className="mb-2 text-[10px] font-semibold uppercase tracking-[.14em] text-slate-400">{eyebrow}</p> : null}<h1 className="text-[30px] font-semibold tracking-[-.055em] text-slate-950 md:text-[34px]">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-500">{description}</p></div>{action}</div>;
}

function Panel({ children, className = "" }: { children: React.ReactNode; className?: string }) {
  return <section className={`rounded-2xl border border-slate-200 bg-white ${className}`}>{children}</section>;
}

function EmptyState({ icon, title, description, action }: { icon: React.ReactNode; title: string; description: string; action?: React.ReactNode }) {
  return <div className="grid min-h-56 place-items-center px-6 py-10 text-center"><div><div className="mx-auto grid h-10 w-10 place-items-center rounded-xl bg-slate-100 text-slate-600">{icon}</div><h3 className="mt-4 text-sm font-semibold text-slate-900">{title}</h3><p className="mx-auto mt-1.5 max-w-sm text-sm leading-6 text-slate-500">{description}</p>{action ? <div className="mt-5">{action}</div> : null}</div></div>;
}

function ErrorState({ title = "We could not load this workspace", description = "Please refresh the page. If the problem continues, try again in a moment." }: { title?: string; description?: string }) {
  return <Panel><div className="grid min-h-72 place-items-center px-6 py-12 text-center"><div><div className="mx-auto grid h-10 w-10 place-items-center rounded-xl bg-red-50 text-red-600">!</div><h2 className="mt-4 text-base font-semibold text-slate-900">{title}</h2><p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-slate-500">{description}</p><Button variant="outline" className="mt-5" onClick={() => window.location.reload()}>Refresh page</Button></div></div></Panel>;
}

function Metric({ label, value, note }: { label: string; value: string; note: string }) {
  return <Panel className="p-5"><p className="text-xs font-medium text-slate-500">{label}</p><p className="mt-2 text-[27px] font-semibold tracking-[-.055em] text-slate-950">{value}</p><p className="mt-2 text-[11px] text-slate-400">{note}</p></Panel>;
}

function Overview() {
  const dashboard = trpc.dashboard.overview.useQuery();
  const creator = trpc.creator.mine.useQuery();
  const [, setLocation] = useLocation();
  const summary = dashboard.data;
  const series = useMemo(() => (summary?.recentOrders ?? []).slice().reverse().map((order) => ({ label: dateText(order.createdAt), value: Number(order.total) })), [summary?.recentOrders]);
  if (dashboard.error || creator.error) return <ErrorState title="Dashboard unavailable" description="We could not retrieve your creator metrics right now." />;
  return <>
    <PageHeading title={creator.data ? `Good morning, ${creator.data.displayName.split(" ")[0]}` : "Good morning"} description="Here’s a quiet view of what is moving in your creator business." action={<Button className="h-10 bg-slate-950 text-white hover:bg-slate-800" onClick={() => setLocation("/app/products")}><Plus className="mr-2 h-4 w-4" />Create offer</Button>} />
    <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-6"><Metric label="Revenue" value={money.format(summary?.revenue ?? 0)} note="Paid orders to date" /><Metric label="MRR" value={money.format(summary?.mrr ?? 0)} note="Active memberships" /><Metric label="Orders" value={`${summary?.orders ?? 0}`} note="Completed purchases" /><Metric label="Customers" value={`${summary?.customers ?? 0}`} note="People in your CRM" /><Metric label="Store views" value={`${summary?.storeViews ?? 0}`} note="Public page loads" /><Metric label="Conversion" value={`${summary?.conversionRate ?? 0}%`} note="Buyers per customer" /></div>
    <div className="mt-6 grid gap-6 xl:grid-cols-[minmax(0,1.45fr)_minmax(320px,.75fr)]">
      <Panel className="p-5 md:p-6"><div className="flex items-start justify-between"><div><h2 className="text-sm font-semibold text-slate-950">Revenue overview</h2><p className="mt-1 text-xs text-slate-400">Paid orders in your current account</p></div><Badge variant="secondary" className="bg-slate-100 text-slate-600">All time</Badge></div>{series.length ? <div className="mt-6 h-64"><ResponsiveContainer width="100%" height="100%"><AreaChart data={series}><defs><linearGradient id="revenue" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#0f172a" stopOpacity={0.15}/><stop offset="100%" stopColor="#0f172a" stopOpacity={0}/></linearGradient></defs><XAxis dataKey="label" tickLine={false} axisLine={false} tick={{ fontSize: 11, fill: "#94a3b8" }}/><Tooltip contentStyle={{ borderRadius: 12, borderColor: "#e2e8f0", fontSize: 12 }} formatter={(value) => money.format(Number(value))}/><Area dataKey="value" stroke="#0f172a" strokeWidth={2.25} fill="url(#revenue)" /></AreaChart></ResponsiveContainer></div> : <EmptyState icon={<ArrowUpRight className="h-5 w-5" />} title="Your revenue story starts here" description="Publish an offer, then CreaDock will turn your paid sales into a useful trend." action={<Button variant="outline" onClick={() => setLocation("/app/products")}>Create a product</Button>} />}</Panel>
      <Panel className="p-5 md:p-6"><div className="flex items-start justify-between"><div><h2 className="text-sm font-semibold text-slate-950">Quick actions</h2><p className="mt-1 text-xs text-slate-400">Build your first offer</p></div><span className="grid h-8 w-8 place-items-center rounded-lg bg-slate-100"><Plus className="h-4 w-4" /></span></div><div className="mt-5 divide-y divide-slate-100">{[{ label: "Digital product", detail: "Sell files and templates", path: "/app/products", icon: Package }, { label: "Course", detail: "Teach lesson by lesson", path: "/app/courses", icon: FileText }, { label: "Booking", detail: "Offer time on your calendar", path: "/app/bookings", icon: CalendarDays }, { label: "Membership", detail: "Create recurring access", path: "/app/memberships", icon: CreditCard }].map((item) => <button onClick={() => setLocation(item.path)} key={item.label} className="flex w-full items-center gap-3 py-3.5 text-left group"><span className="grid h-8 w-8 place-items-center rounded-lg bg-slate-50 text-slate-600 group-hover:bg-slate-950 group-hover:text-white"><item.icon className="h-4 w-4" /></span><span className="flex-1"><span className="block text-sm font-medium text-slate-800">{item.label}</span><span className="block text-[11px] text-slate-400">{item.detail}</span></span><ChevronRight className="h-4 w-4 text-slate-300" /></button>)}</div></Panel>
    </div>
    <Panel className="mt-6 overflow-hidden"><div className="flex items-center justify-between border-b border-slate-100 px-5 py-4 md:px-6"><div><h2 className="text-sm font-semibold text-slate-950">Recent orders</h2><p className="mt-1 text-xs text-slate-400">The most recent activity from your storefront.</p></div><button className="text-xs font-medium text-slate-700 hover:text-slate-950" onClick={() => setLocation("/app/customers")}>View customers</button></div>{summary?.recentOrders?.length ? <div className="overflow-x-auto"><table className="w-full min-w-[620px] text-left"><thead className="bg-slate-50/70 text-[10px] uppercase tracking-[.11em] text-slate-400"><tr><th className="px-5 py-3 font-semibold">Order</th><th className="px-5 py-3 font-semibold">Date</th><th className="px-5 py-3 font-semibold">Status</th><th className="px-5 py-3 text-right font-semibold">Amount</th></tr></thead><tbody className="divide-y divide-slate-100">{summary.recentOrders.slice(0, 5).map((order) => <tr key={order.id} className="text-sm"><td className="px-5 py-4 font-medium text-slate-700">{order.orderNumber}</td><td className="px-5 py-4 text-slate-500">{dateText(order.createdAt)}</td><td className="px-5 py-4"><Badge className={order.status === "paid" ? "bg-emerald-50 text-emerald-700 hover:bg-emerald-50" : "bg-amber-50 text-amber-700 hover:bg-amber-50"}>{order.status}</Badge></td><td className="px-5 py-4 text-right font-medium text-slate-800">{money.format(Number(order.total))}</td></tr>)}</tbody></table></div> : <EmptyState icon={<CreditCard className="h-5 w-5" />} title="No orders yet" description="Once your storefront starts selling, new orders will appear here with their payment status." />}</Panel>
  </>;
}

function Products() {
  const products = trpc.products.list.useQuery(); const save = trpc.products.save.useMutation({ onSuccess: () => { toast.success("Offer saved"); products.refetch(); setOpen(false); setEditingId(undefined); } });
  if (products.error) return <ErrorState title="Products unavailable" description="We could not retrieve your product catalog right now." />;
  const [open, setOpen] = useState(false); const [editingId, setEditingId] = useState<number | undefined>(); const [name, setName] = useState(""); const [description, setDescription] = useState(""); const [price, setPrice] = useState("0"); const [type, setType] = useState<"digital" | "course" | "service" | "membership" | "external">("digital"); const [status, setStatus] = useState<"draft" | "published" | "archived">("draft"); const [fileUrl, setFileUrl] = useState(""); const [fileSizeBytes, setFileSizeBytes] = useState(0); const [uploading, setUploading] = useState(false);
  const uploadFile = async (file: File) => { setUploading(true); try { const response = await fetch(`/api/uploads/product?name=${encodeURIComponent(file.name)}`, { method: "POST", headers: { "Content-Type": "application/octet-stream", "X-Content-Type": file.type || "application/octet-stream" }, body: file }); if (!response.ok) throw new Error("Upload could not be completed"); const data = await response.json(); setFileUrl(data.url); setFileSizeBytes(Number(data.sizeBytes) || file.size); toast.success("File uploaded securely"); } catch (error) { toast.error(error instanceof Error ? error.message : "Upload failed"); } finally { setUploading(false); } };
  const beginNew = () => { setEditingId(undefined); setName(""); setDescription(""); setPrice("0"); setType("digital"); setStatus("draft"); setFileUrl(""); setFileSizeBytes(0); setOpen(true); };
  const beginEdit = (product: NonNullable<typeof products.data>[number]) => { setEditingId(product.id); setName(product.name); setDescription(product.description || ""); setPrice(String(product.price)); setType(product.type); setStatus(product.status); setFileUrl(product.fileUrl || ""); setFileSizeBytes(product.fileSizeBytes || 0); setOpen(true); };
  return <><PageHeading eyebrow="Sell" title="Products" description="Create sellable files, resources, services, and external offers from one focused catalog." action={<Button onClick={beginNew} className="h-10 bg-slate-950 text-white hover:bg-slate-800"><Plus className="mr-2 h-4 w-4" />New product</Button>} />{open ? <Panel className="mb-6 p-5 md:p-6"><div className="grid gap-4 md:grid-cols-2"><div className="space-y-2"><Label>Product name</Label><Input value={name} onChange={(e) => setName(e.target.value)} className={fieldClass} placeholder="The creator kit" /></div><div className="space-y-2"><Label>Price (USD)</Label><Input value={price} inputMode="decimal" onChange={(e) => setPrice(e.target.value)} className={fieldClass} /></div><div className="space-y-2"><Label>Offer type</Label><select className={`${fieldClass} w-full rounded-md px-3`} value={type} onChange={(e) => setType(e.target.value as typeof type)}><option value="digital">Digital download</option><option value="service">Service</option><option value="external">External resource</option></select></div><div className="space-y-2"><Label>Publish state</Label><select className={`${fieldClass} w-full rounded-md px-3`} value={status} onChange={(e) => setStatus(e.target.value as typeof status)}><option value="draft">Draft</option><option value="published">Published</option><option value="archived">Archived</option></select></div><div className="space-y-2"><Label>Digital file</Label><Input type="file" className={`${fieldClass} cursor-pointer`} disabled={type !== "digital" || uploading} onChange={(e) => { const file = e.target.files?.[0]; if (file) uploadFile(file); }} /><p className="text-[11px] text-slate-400">{fileUrl ? `File stored securely${fileSizeBytes ? ` · ${(fileSizeBytes / 1024 / 1024).toFixed(2)} MB` : ""}` : type === "digital" ? "PDF, template, preset, audio, or ZIP" : "Not needed for this offer"}</p></div><div className="space-y-2 md:col-span-2"><Label>Description</Label><Textarea value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Explain what your customer gets." className="min-h-24 border-slate-200 bg-white focus-visible:ring-slate-950" /></div></div><div className="mt-5 flex justify-end gap-2"><Button variant="outline" onClick={() => setOpen(false)}>Cancel</Button><Button disabled={!name || save.isPending || uploading} className="bg-slate-950 text-white hover:bg-slate-800" onClick={() => save.mutate({ id: editingId, name, description, type, price, status, fileUrl, fileSizeBytes })}>{save.isPending ? "Saving…" : editingId ? "Save changes" : "Save offer"}</Button></div></Panel> : null}<Panel className="overflow-hidden">{products.data?.length ? <div className="divide-y divide-slate-100">{products.data.map((product) => <div className="flex items-center gap-4 px-5 py-4 md:px-6" key={product.id}><span className="grid h-10 w-10 place-items-center rounded-xl bg-slate-100 text-slate-600"><Package className="h-4 w-4" /></span><div className="min-w-0 flex-1"><p className="truncate text-sm font-medium text-slate-800">{product.name}</p><p className="mt-0.5 text-xs text-slate-400">{product.type} · {product.fileUrl ? "File attached" : "No file attached"}</p></div><Badge variant="secondary" className="hidden bg-slate-100 text-slate-600 sm:inline-flex">{product.status}</Badge><button className="text-xs font-medium text-slate-600 hover:text-slate-950" onClick={() => beginEdit(product)}>Edit</button><p className="w-20 text-right text-sm font-semibold text-slate-800">{money.format(Number(product.price))}</p></div>)}</div> : <EmptyState icon={<Package className="h-5 w-5" />} title="Create your first offer" description="Start with a download, template, preset, resource, or service. You can publish it when it is ready." action={<Button onClick={beginNew}><Plus className="mr-2 h-4 w-4" />New product</Button>} />}</Panel></>;
}

function Courses() {
  const courseList = trpc.courses.list.useQuery();
  const [open, setOpen] = useState(false); const [selectedId, setSelectedId] = useState<number | null>(null); const [title, setTitle] = useState(""); const [description, setDescription] = useState(""); const [lessonTitle, setLessonTitle] = useState(""); const [lessonBody, setLessonBody] = useState(""); const [lessonKind, setLessonKind] = useState<"text" | "video" | "download">("text"); const [editingLessonId, setEditingLessonId] = useState<number | null>(null);
  const create = trpc.courses.create.useMutation({ onSuccess: (id) => { toast.success("Course created"); courseList.refetch(); setSelectedId(id); setOpen(false); } });
  const update = trpc.courses.update.useMutation({ onSuccess: () => { toast.success("Course updated"); courseList.refetch(); } });
  const lessons = trpc.courses.lessons.useQuery({ courseId: selectedId ?? 0 }, { enabled: Boolean(selectedId) });
  const addLesson = trpc.courses.addLesson.useMutation({ onSuccess: () => { toast.success("Lesson added"); lessons.refetch(); setLessonTitle(""); setLessonBody(""); } });
  const updateLesson = trpc.courses.updateLesson.useMutation({ onSuccess: () => { toast.success("Lesson updated"); lessons.refetch(); setEditingLessonId(null); setLessonTitle(""); setLessonBody(""); } });
  const deleteLesson = trpc.courses.deleteLesson.useMutation({ onSuccess: () => { toast.success("Lesson removed"); lessons.refetch(); } });
  const reorderLessons = trpc.courses.reorderLessons.useMutation({ onSuccess: () => lessons.refetch() });
  const progress = trpc.courses.progress.useQuery({ courseId: selectedId ?? 0 }, { enabled: Boolean(selectedId) });
  const selected = courseList.data?.find((course) => course.id === selectedId);
  if (courseList.error || lessons.error || progress.error) return <ErrorState title="Courses unavailable" description="We could not retrieve course content or learner progress right now." />;
  const moveLesson = (from: number, direction: -1 | 1) => { if (!selected || !lessons.data) return; const to = from + direction; if (to < 0 || to >= lessons.data.length) return; const ordered = [...lessons.data]; [ordered[from], ordered[to]] = [ordered[to], ordered[from]]; reorderLessons.mutate({ courseId: selected.id, lessonIds: ordered.map((lesson) => lesson.id) }); };
  const startEdit = (lesson: NonNullable<typeof lessons.data>[number]) => { setEditingLessonId(lesson.id); setLessonTitle(lesson.title); setLessonBody(lesson.body || ""); setLessonKind(lesson.kind); };
  const saveLesson = () => { if (!selected || !lessonTitle) return; if (editingLessonId) updateLesson.mutate({ id: editingLessonId, courseId: selected.id, title: lessonTitle, kind: lessonKind, body: lessonBody || undefined }); else addLesson.mutate({ courseId: selected.id, title: lessonTitle, kind: lessonKind, body: lessonBody || undefined }); };
  return <><PageHeading eyebrow="Teach" title="Courses" description="Build structured learning experiences with rich text, video, downloadable lessons, and trackable student progress." action={<Button className="h-10 bg-slate-950 text-white hover:bg-slate-800" onClick={() => setOpen(!open)}><Plus className="mr-2 h-4 w-4" />New course</Button>} />{open ? <Panel className="mb-6 p-5"><div className="grid gap-4 md:grid-cols-2"><div className="space-y-2"><Label>Course title</Label><Input className={fieldClass} value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Build your creative practice" /></div><div className="space-y-2"><Label>Course description</Label><Input className={fieldClass} value={description} onChange={(e) => setDescription(e.target.value)} placeholder="What learners will achieve" /></div></div><div className="mt-5 flex justify-end gap-2"><Button variant="outline" onClick={() => setOpen(false)}>Cancel</Button><Button disabled={!title || create.isPending} className="bg-slate-950 text-white" onClick={() => create.mutate({ title, description })}>Save course</Button></div></Panel> : null}{selected ? <Panel className="mb-6 p-5 md:p-6"><div className="flex flex-col gap-4 border-b border-slate-100 pb-5 sm:flex-row sm:items-start sm:justify-between"><div><p className="text-sm font-semibold text-slate-900">{selected.title}</p><p className="mt-1 text-xs text-slate-400">Author lessons and track enrolled learners from one place.</p></div><div className="flex gap-2"><Button variant="outline" size="sm" onClick={() => setSelectedId(null)}>Close</Button><Button size="sm" className="bg-slate-950 text-white" disabled={update.isPending} onClick={() => update.mutate({ id: selected.id, title: selected.title, description: selected.description || undefined, status: selected.status === "published" ? "draft" : "published" })}>{selected.status === "published" ? "Unpublish" : "Publish course"}</Button></div></div><div className="mt-5 grid gap-3 md:grid-cols-[1fr_160px]"><Input value={lessonTitle} onChange={(e) => setLessonTitle(e.target.value)} placeholder="Lesson title" /><select className={`${fieldClass} rounded-md px-3`} value={lessonKind} onChange={(e) => setLessonKind(e.target.value as typeof lessonKind)}><option value="text">Text lesson</option><option value="video">Video lesson</option><option value="download">Download lesson</option></select><Textarea className="min-h-20 border-slate-200 md:col-span-2" value={lessonBody} onChange={(e) => setLessonBody(e.target.value)} placeholder="Lesson notes or a short instruction for your students." /></div><div className="mt-3 flex justify-end gap-2">{editingLessonId ? <Button size="sm" variant="outline" onClick={() => { setEditingLessonId(null); setLessonTitle(""); setLessonBody(""); }}>Cancel edit</Button> : null}<Button size="sm" disabled={!lessonTitle || addLesson.isPending || updateLesson.isPending} onClick={saveLesson}>{editingLessonId ? "Save lesson" : <><Plus className="mr-2 h-3.5 w-3.5" />Add lesson</>}</Button></div><div className="mt-5 divide-y divide-slate-100 rounded-xl border border-slate-100">{lessons.data?.length ? lessons.data.map((lesson, index) => <div key={lesson.id} className="flex items-center gap-3 px-4 py-3"><span className="grid h-6 w-6 place-items-center rounded-full bg-slate-100 text-[11px] text-slate-500">{index + 1}</span><div className="min-w-0 flex-1"><p className="truncate text-sm font-medium text-slate-700">{lesson.title}</p><p className="text-[11px] text-slate-400">{lesson.kind}</p></div><div className="flex gap-1"><Button size="sm" variant="ghost" disabled={index === 0} onClick={() => moveLesson(index, -1)}>↑</Button><Button size="sm" variant="ghost" disabled={index === lessons.data.length - 1} onClick={() => moveLesson(index, 1)}>↓</Button><Button size="sm" variant="outline" onClick={() => startEdit(lesson)}>Edit</Button><Button size="sm" variant="ghost" className="text-red-600" onClick={() => deleteLesson.mutate({ id: lesson.id, courseId: selected.id })}>Remove</Button></div></div>) : <p className="px-4 py-8 text-center text-sm text-slate-400">No lessons yet. Add the first one above.</p>}</div><div className="mt-6"><p className="text-xs font-semibold uppercase tracking-[.12em] text-slate-400">Student progress</p><div className="mt-3 divide-y divide-slate-100 rounded-xl border border-slate-100">{progress.data?.length ? progress.data.map((entry) => <div key={entry.enrollments.id} className="flex items-center justify-between px-4 py-3"><div><p className="text-sm font-medium text-slate-700">{entry.customers.name || entry.customers.email}</p><p className="text-xs text-slate-400">{entry.enrollments.completedLessonIds.length} lessons completed</p></div><Badge className="bg-slate-100 text-slate-600 hover:bg-slate-100">Enrolled</Badge></div>) : <p className="px-4 py-6 text-sm text-slate-400">No enrolled learners yet.</p>}</div></div></Panel> : null}<Panel>{courseList.data?.length ? <div className="divide-y divide-slate-100">{courseList.data.map((course) => <div key={course.id} className="flex items-center gap-4 px-5 py-4 md:px-6"><span className="grid h-10 w-10 place-items-center rounded-xl bg-slate-100"><FileText className="h-4 w-4 text-slate-600" /></span><div className="flex-1"><p className="text-sm font-medium text-slate-800">{course.title}</p><p className="mt-0.5 text-xs text-slate-400">{course.description || "No course description yet"}</p></div><Badge variant="secondary" className="bg-slate-100 text-slate-600">{course.status}</Badge><Button size="sm" variant="outline" onClick={() => setSelectedId(course.id)}>Manage</Button></div>)}</div> : <EmptyState icon={<FileText className="h-5 w-5" />} title="Turn your expertise into a course" description="Create the course shell, add lessons, then offer it through your storefront." action={<Button onClick={() => setOpen(true)}><Plus className="mr-2 h-4 w-4" />New course</Button>} />}</Panel></>;
}

function Bookings() { const services = trpc.bookings.services.useQuery(); const appointments = trpc.bookings.appointments.useQuery(); const [open, setOpen] = useState(false); const [selectedId, setSelectedId] = useState<number | null>(null); const [name, setName] = useState(""); const [price, setPrice] = useState("0"); const [duration, setDuration] = useState("30"); const [capacity, setCapacity] = useState("1"); const [startsAt, setStartsAt] = useState(""); const create = trpc.bookings.createService.useMutation({ onSuccess: (id) => { toast.success("Published service created"); services.refetch(); setSelectedId(id); setOpen(false); } }); const availability = trpc.bookings.availability.useQuery({ serviceId: selectedId ?? 0 }, { enabled: Boolean(selectedId) }); const addAvailability = trpc.bookings.addAvailability.useMutation({ onSuccess: () => { toast.success("Availability added"); availability.refetch(); setStartsAt(""); } }); const updateAppointment = trpc.bookings.updateAppointment.useMutation({ onSuccess: () => { toast.success("Appointment updated"); appointments.refetch(); } }); const selected = services.data?.find((service) => service.id === selectedId); const addSlot = () => { if (!selected || !startsAt) return; const start = new Date(startsAt); const end = new Date(start.getTime() + selected.durationMinutes * 60_000); addAvailability.mutate({ serviceId: selected.id, startsAt: start, endsAt: end }); }; return <><PageHeading eyebrow="Meet" title="Bookings" description="Offer focused one-to-one and group sessions. Add services, control availability, and manage every client reservation." action={<Button className="h-10 bg-slate-950 text-white" onClick={() => setOpen(!open)}><Plus className="mr-2 h-4 w-4" />New service</Button>} />{open ? <Panel className="mb-6 p-5"><div className="grid gap-4 md:grid-cols-4"><div className="space-y-2"><Label>Service name</Label><Input className={fieldClass} value={name} onChange={(e) => setName(e.target.value)} placeholder="Strategy session" /></div><div className="space-y-2"><Label>Duration</Label><Input className={fieldClass} type="number" value={duration} onChange={(e) => setDuration(e.target.value)} /></div><div className="space-y-2"><Label>Seats</Label><Input className={fieldClass} type="number" min="1" value={capacity} onChange={(e) => setCapacity(e.target.value)} /></div><div className="space-y-2"><Label>Price</Label><Input className={fieldClass} value={price} onChange={(e) => setPrice(e.target.value)} /></div></div><p className="mt-3 text-xs text-slate-400">Use more than one seat to make this a group session.</p><div className="mt-5 flex justify-end gap-2"><Button variant="outline" onClick={() => setOpen(false)}>Cancel</Button><Button disabled={!name || create.isPending} className="bg-slate-950 text-white" onClick={() => create.mutate({ name, price, durationMinutes: Number(duration), capacity: Number(capacity), status: "published" })}>Publish service</Button></div></Panel> : null}{selected ? <Panel className="mb-6 p-5"><div className="flex items-center justify-between"><div><p className="text-sm font-semibold text-slate-900">Availability for {selected.name}</p><p className="mt-1 text-xs text-slate-400">Open times appear as reservable sessions on your public storefront.</p></div><Button size="sm" variant="outline" onClick={() => setSelectedId(null)}>Close</Button></div><div className="mt-4 flex flex-col gap-2 sm:flex-row"><Input className={fieldClass} type="datetime-local" value={startsAt} onChange={(event) => setStartsAt(event.target.value)} /><Button disabled={!startsAt || addAvailability.isPending} onClick={addSlot}>Add time</Button></div><div className="mt-4 divide-y divide-slate-100 rounded-xl border border-slate-100">{availability.data?.length ? availability.data.map((slot) => <div className="flex items-center justify-between px-4 py-3 text-sm" key={slot.id}><span className="text-slate-700">{new Date(slot.startsAt).toLocaleString()}</span><Badge className={slot.isBooked ? "bg-amber-50 text-amber-700 hover:bg-amber-50" : "bg-emerald-50 text-emerald-700 hover:bg-emerald-50"}>{slot.isBooked ? "Booked" : "Open"}</Badge></div>) : <p className="px-4 py-8 text-center text-sm text-slate-400">No availability yet.</p>}</div></Panel> : null}<Panel>{services.data?.length ? <div className="divide-y divide-slate-100">{services.data.map((service) => <div className="flex items-center gap-4 px-5 py-4 md:px-6" key={service.id}><span className="grid h-10 w-10 place-items-center rounded-xl bg-slate-100"><CalendarDays className="h-4 w-4 text-slate-600" /></span><div className="flex-1"><p className="text-sm font-medium text-slate-800">{service.name}</p><p className="mt-0.5 text-xs text-slate-400">{service.durationMinutes} minutes · {service.capacity === 1 ? "1:1" : `${service.capacity} seats`}</p></div><Badge className="bg-emerald-50 text-emerald-700 hover:bg-emerald-50">{service.status}</Badge><Button size="sm" variant="outline" onClick={() => setSelectedId(service.id)}>Availability</Button><p className="text-sm font-semibold text-slate-800">{money.format(Number(service.price))}</p></div>)}</div> : <EmptyState icon={<CalendarDays className="h-5 w-5" />} title="Make time bookable" description="Create a service, publish its availability, and give your audience a simple way to reserve time with you." action={<Button onClick={() => setOpen(true)}><Plus className="mr-2 h-4 w-4" />New service</Button>} />}</Panel><Panel className="mt-6 overflow-hidden"><div className="border-b border-slate-100 px-5 py-4"><h2 className="text-sm font-semibold text-slate-950">Appointment management</h2><p className="mt-1 text-xs text-slate-400">Keep your booking queue current as you confirm, complete, or cancel sessions.</p></div>{appointments.data?.length ? <div className="divide-y divide-slate-100">{appointments.data.map((entry) => <div key={entry.appointments.id} className="flex flex-wrap items-center gap-3 px-5 py-4"><div className="min-w-0 flex-1"><p className="text-sm font-medium text-slate-800">{entry.customers.name || entry.customers.email}</p><p className="mt-1 text-xs text-slate-400">{entry.services.name} · {new Date(entry.appointments.createdAt).toLocaleDateString()}</p></div><Badge className={entry.appointments.status === "completed" ? "bg-emerald-50 text-emerald-700 hover:bg-emerald-50" : "bg-slate-100 text-slate-600 hover:bg-slate-100"}>{entry.appointments.status}</Badge><select className="h-8 rounded-md border border-slate-200 bg-white px-2 text-xs" value={entry.appointments.status} onChange={(event) => updateAppointment.mutate({ id: entry.appointments.id, status: event.target.value as "pending" | "confirmed" | "cancelled" | "completed" })}><option value="pending">Pending</option><option value="confirmed">Confirmed</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select></div>)}</div> : <p className="px-5 py-10 text-center text-sm text-slate-400">New public reservations will appear here.</p>}</Panel></> }

function Memberships() { const plans = trpc.memberships.list.useQuery(); const subscribers = trpc.memberships.subscribers.useQuery(); const create = trpc.memberships.create.useMutation({ onSuccess: () => { toast.success("Membership plan published"); plans.refetch(); setOpen(false); } }); const updateSubscriber = trpc.memberships.updateSubscriber.useMutation({ onSuccess: () => { toast.success("Subscriber status updated"); subscribers.refetch(); } }); const [open, setOpen] = useState(false); const [name, setName] = useState(""); const [price, setPrice] = useState("10"); const [benefits, setBenefits] = useState(""); return <><PageHeading eyebrow="Recurring revenue" title="Memberships" description="Offer tiered, recurring access to your most valuable content, community, and ongoing learning." action={<Button className="h-10 bg-slate-950 text-white" onClick={() => setOpen(!open)}><Plus className="mr-2 h-4 w-4" />New plan</Button>} />{open ? <Panel className="mb-6 p-5"><div className="grid gap-4 md:grid-cols-3"><div className="space-y-2"><Label>Plan name</Label><Input className={fieldClass} value={name} onChange={(e) => setName(e.target.value)} placeholder="Studio membership" /></div><div className="space-y-2"><Label>Monthly price</Label><Input className={fieldClass} value={price} onChange={(e) => setPrice(e.target.value)} /></div><div className="space-y-2"><Label>Benefits</Label><Input className={fieldClass} value={benefits} onChange={(e) => setBenefits(e.target.value)} placeholder="Monthly workshop, private library" /></div></div><p className="mt-3 text-xs text-slate-400">New plans are published immediately for the in-app MVP storefront.</p><div className="mt-5 flex justify-end gap-2"><Button variant="outline" onClick={() => setOpen(false)}>Cancel</Button><Button disabled={!name || create.isPending} className="bg-slate-950 text-white" onClick={() => create.mutate({ name, price, benefits: benefits.split(",").map((v) => v.trim()).filter(Boolean), interval: "month", status: "published" })}>Publish plan</Button></div></Panel> : null}<Panel>{plans.data?.length ? <div className="divide-y divide-slate-100">{plans.data.map((plan) => <div className="flex items-center gap-4 px-5 py-4 md:px-6" key={plan.id}><span className="grid h-10 w-10 place-items-center rounded-xl bg-slate-100"><CreditCard className="h-4 w-4 text-slate-600" /></span><div className="flex-1"><p className="text-sm font-medium text-slate-800">{plan.name}</p><p className="mt-0.5 text-xs text-slate-400">{(plan.benefits ?? []).length} member benefits</p></div><Badge className={plan.status === "published" ? "bg-emerald-50 text-emerald-700 hover:bg-emerald-50" : "bg-slate-100 text-slate-600 hover:bg-slate-100"}>{plan.status}</Badge><p className="text-sm font-semibold text-slate-800">{money.format(Number(plan.price))}<span className="font-normal text-slate-400">/{plan.interval === "month" ? "mo" : "yr"}</span></p></div>)}</div> : <EmptyState icon={<CreditCard className="h-5 w-5" />} title="Offer ongoing access" description="Memberships make it simple to package valuable content and community into dependable recurring revenue." action={<Button onClick={() => setOpen(true)}><Plus className="mr-2 h-4 w-4" />New membership</Button>} />}</Panel><Panel className="mt-6 overflow-hidden"><div className="border-b border-slate-100 px-5 py-4"><h2 className="text-sm font-semibold text-slate-950">Active subscribers</h2><p className="mt-1 text-xs text-slate-400">Review active members and update their in-app access status.</p></div>{subscribers.data?.length ? <div className="divide-y divide-slate-100">{subscribers.data.map((entry) => <div key={entry.subscriptions.id} className="flex flex-wrap items-center gap-3 px-5 py-4"><div className="min-w-0 flex-1"><p className="text-sm font-medium text-slate-800">{entry.customers.name || entry.customers.email}</p><p className="mt-1 text-xs text-slate-400">{entry.membershipPlans.name} · {entry.customers.email}</p></div><select className="h-8 rounded-md border border-slate-200 bg-white px-2 text-xs" value={entry.subscriptions.status} disabled={updateSubscriber.isPending} onChange={(event) => updateSubscriber.mutate({ id: entry.subscriptions.id, status: event.target.value as "active" | "past_due" | "cancelled" | "paused" })}><option value="active">Active</option><option value="past_due">Past due</option><option value="paused">Paused</option><option value="cancelled">Cancelled</option></select></div>)}</div> : <p className="px-5 py-10 text-center text-sm text-slate-400">Your active members will appear here.</p>}</Panel></> }

function Customers() { const customers = trpc.customers.list.useQuery(); const [open, setOpen] = useState(false); const [selectedId, setSelectedId] = useState<number | null>(null); const [email, setEmail] = useState(""); const [name, setName] = useState(""); const [tags, setTags] = useState(""); const save = trpc.customers.save.useMutation({ onSuccess: () => { toast.success("Customer saved"); customers.refetch(); setOpen(false); } }); const activity = trpc.customers.activity.useQuery({ customerId: selectedId ?? 0 }, { enabled: Boolean(selectedId) }); const selected = customers.data?.find((customer) => customer.id === selectedId); return <><PageHeading eyebrow="Audience" title="Customers" description="A unified view of buyers, members, students, and subscribers—all in one intentional CRM." action={<Button className="h-10 bg-slate-950 text-white" onClick={() => setOpen(!open)}><Plus className="mr-2 h-4 w-4" />Add customer</Button>} />{open ? <Panel className="mb-6 p-5"><div className="grid gap-4 md:grid-cols-3"><div className="space-y-2"><Label>Name</Label><Input className={fieldClass} value={name} onChange={(e) => setName(e.target.value)} placeholder="Alex Morgan" /></div><div className="space-y-2"><Label>Email</Label><Input className={fieldClass} type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="alex@example.com" /></div><div className="space-y-2"><Label>Tags</Label><Input className={fieldClass} value={tags} onChange={(e) => setTags(e.target.value)} placeholder="customer, newsletter" /></div></div><div className="mt-5 flex justify-end gap-2"><Button variant="outline" onClick={() => setOpen(false)}>Cancel</Button><Button disabled={!email || save.isPending} className="bg-slate-950 text-white" onClick={() => save.mutate({ name, email, tags: tags.split(",").map((tag) => tag.trim()).filter(Boolean), marketingOptIn: false })}>Save contact</Button></div></Panel> : null}{selected ? <Panel className="mb-6 p-5"><div className="flex items-start justify-between"><div><p className="text-sm font-semibold text-slate-900">{selected.name || selected.email}</p><p className="mt-1 text-xs text-slate-400">{selected.email} · customer history</p></div><Button size="sm" variant="outline" onClick={() => setSelectedId(null)}>Close</Button></div><div className="mt-5 grid gap-4 md:grid-cols-2"><div className="rounded-xl bg-slate-50 p-4"><p className="text-xs font-medium text-slate-400">Orders</p>{activity.data?.purchaseHistory.length ? <div className="mt-3 space-y-2">{activity.data.purchaseHistory.map((order) => <div className="flex justify-between text-sm" key={order.id}><span className="text-slate-600">{order.orderNumber}</span><span className="font-medium text-slate-800">{money.format(Number(order.total))}</span></div>)}</div> : <p className="mt-3 text-sm text-slate-400">No purchases yet.</p>}</div><div className="rounded-xl bg-slate-50 p-4"><p className="text-xs font-medium text-slate-400">Memberships</p>{activity.data?.memberships.length ? <div className="mt-3 space-y-2">{activity.data.memberships.map((entry) => <p className="text-sm text-slate-700" key={entry.subscriptions.id}>{entry.membershipPlans.name} · <span className="text-slate-400">{entry.subscriptions.status}</span></p>)}</div> : <p className="mt-3 text-sm text-slate-400">No memberships yet.</p>}</div><div className="rounded-xl bg-slate-50 p-4"><p className="text-xs font-medium text-slate-400">Bookings</p>{activity.data?.bookings.length ? <div className="mt-3 space-y-2">{activity.data.bookings.map((entry) => <p className="text-sm text-slate-700" key={entry.appointments.id}>{entry.services.name} · <span className="text-slate-400">{entry.appointments.status}</span></p>)}</div> : <p className="mt-3 text-sm text-slate-400">No bookings yet.</p>}</div><div className="rounded-xl bg-slate-50 p-4"><p className="text-xs font-medium text-slate-400">Courses</p>{activity.data?.enrollments.length ? <div className="mt-3 space-y-2">{activity.data.enrollments.map((entry) => <p className="text-sm text-slate-700" key={entry.enrollments.id}>{entry.courses.title} · <span className="text-slate-400">{entry.enrollments.completedLessonIds.length} complete</span></p>)}</div> : <p className="mt-3 text-sm text-slate-400">No course progress yet.</p>}</div></div></Panel> : null}<Panel className="overflow-hidden">{customers.data?.length ? <div className="overflow-x-auto"><table className="w-full min-w-[640px] text-left"><thead className="bg-slate-50 text-[10px] uppercase tracking-[.11em] text-slate-400"><tr><th className="px-5 py-3">Customer</th><th className="px-5 py-3">Tags</th><th className="px-5 py-3">Marketing</th><th className="px-5 py-3 text-right">Added</th></tr></thead><tbody className="divide-y divide-slate-100">{customers.data.map((customer) => <tr key={customer.id}><td className="px-5 py-4"><p className="text-sm font-medium text-slate-800">{customer.name || "Unnamed contact"}</p><p className="text-xs text-slate-400">{customer.email}</p></td><td className="px-5 py-4">{customer.tags?.length ? customer.tags.map((tag) => <Badge key={tag} variant="secondary" className="mr-1 bg-slate-100 text-slate-600">{tag}</Badge>) : <span className="text-xs text-slate-400">—</span>}</td><td className="px-5 py-4 text-xs text-slate-500">{customer.marketingOptIn ? "Subscribed" : "Not subscribed"}</td><td className="px-5 py-4 text-right"><Button size="sm" variant="outline" onClick={() => setSelectedId(customer.id)}>View history</Button></td></tr>)}</tbody></table></div> : <EmptyState icon={<Users className="h-5 w-5" />} title="Your audience will gather here" description="Add contacts manually or collect them from your published storefront and checkout." action={<Button onClick={() => setOpen(true)}><Plus className="mr-2 h-4 w-4" />Add customer</Button>} />}</Panel></> }

function Email() {
  const marketing = trpc.marketing.overview.useQuery();
  const [audienceName, setAudienceName] = useState(""); const [subject, setSubject] = useState(""); const [body, setBody] = useState(""); const [sequenceName, setSequenceName] = useState("");
  const audience = trpc.marketing.createAudience.useMutation({ onSuccess: () => { toast.success("Audience created"); marketing.refetch(); } });
  const campaign = trpc.marketing.createCampaign.useMutation({ onSuccess: () => { toast.success("MVP broadcast saved"); marketing.refetch(); setSubject(""); setBody(""); } });
  const markSent = trpc.marketing.markSent.useMutation({ onSuccess: () => { toast.success("Broadcast marked sent in MVP"); marketing.refetch(); } });
  const sequence = trpc.marketing.createSequence.useMutation({ onSuccess: () => { toast.success("Welcome sequence activated"); marketing.refetch(); setSequenceName(""); } });
  if (marketing.error) return <ErrorState title="Email workspace unavailable" description="We could not retrieve your audiences and broadcasts right now." />;
  return <><PageHeading eyebrow="Marketing" title="Email" description="Build audiences, craft broadcasts, and map welcome sequences in the in-app CreaDock MVP." /><div className="grid gap-6 xl:grid-cols-[1.1fr_.9fr]"><Panel className="p-5 md:p-6"><h2 className="text-sm font-semibold text-slate-950">Create a broadcast</h2><p className="mt-1 text-xs leading-5 text-slate-400">Saving or sending is recorded in CreaDock only; no real email is delivered in this MVP.</p><div className="mt-5 space-y-4"><div className="space-y-2"><Label>Subject line</Label><Input className={fieldClass} value={subject} onChange={(event) => setSubject(event.target.value)} placeholder="A note for your creative week" /></div><div className="space-y-2"><Label>Message</Label><Textarea className="min-h-36 border-slate-200 bg-white focus-visible:ring-slate-950" value={body} onChange={(event) => setBody(event.target.value)} placeholder="Write a useful, human message…" /></div><Button disabled={!subject || !body || campaign.isPending} className="bg-slate-950 text-white" onClick={() => campaign.mutate({ subject, body, status: "draft" })}><Send className="mr-2 h-4 w-4" />Save broadcast</Button></div></Panel><Panel className="p-5 md:p-6"><h2 className="text-sm font-semibold text-slate-950">Welcome sequence</h2><p className="mt-1 text-xs leading-5 text-slate-400">Define a first-step journey triggered when someone joins your list.</p><div className="mt-5 space-y-4"><div className="space-y-2"><Label>Sequence name</Label><Input className={fieldClass} value={sequenceName} onChange={(event) => setSequenceName(event.target.value)} placeholder="New subscriber welcome" /></div><div className="rounded-xl border border-slate-100 bg-slate-50 px-4 py-3"><p className="text-xs font-medium text-slate-700">Email 1 · immediately</p><p className="mt-1 text-xs text-slate-400">A welcoming introduction from your creator business.</p></div><Button disabled={!sequenceName || sequence.isPending} variant="outline" className="border-slate-300" onClick={() => sequence.mutate({ name: sequenceName, trigger: "signup", steps: [{ subject: "Welcome — I’m glad you’re here", body: "Thanks for joining. Here is how to get the most from my work.", delayDays: 0 }] })}><Mail className="mr-2 h-4 w-4" />Activate sequence</Button></div></Panel></div><Panel className="mt-6 overflow-hidden"><div className="border-b border-slate-100 px-5 py-4"><h2 className="text-sm font-semibold text-slate-950">Your marketing workspace</h2></div><div className="grid divide-y divide-slate-100 md:grid-cols-3 md:divide-x md:divide-y-0"><div className="p-5"><p className="text-xs text-slate-400">Audiences</p><p className="mt-2 text-2xl font-semibold tracking-[-.05em] text-slate-950">{marketing.data?.audiences.length ?? 0}</p><div className="mt-4 flex gap-2"><Input className="h-8 text-xs" value={audienceName} onChange={(event) => setAudienceName(event.target.value)} placeholder="Newsletter" /><Button size="sm" disabled={!audienceName || audience.isPending} onClick={() => audience.mutate({ name: audienceName })}>Add</Button></div></div><div className="p-5"><p className="text-xs text-slate-400">Broadcasts</p><p className="mt-2 text-2xl font-semibold tracking-[-.05em] text-slate-950">{marketing.data?.campaigns.length ?? 0}</p><p className="mt-3 text-xs text-slate-400">Mark a saved draft as sent to test the campaign lifecycle.</p></div><div className="p-5"><p className="text-xs text-slate-400">Automations</p><p className="mt-2 text-2xl font-semibold tracking-[-.05em] text-slate-950">{marketing.data?.sequences.length ?? 0}</p><p className="mt-3 text-xs text-slate-400">Sequence structure is saved and ready to preview.</p></div></div>{marketing.data?.campaigns.length ? <div className="border-t border-slate-100"><p className="px-5 pt-4 text-xs font-semibold uppercase tracking-[.12em] text-slate-400">Recent broadcasts</p>{marketing.data.campaigns.slice(0, 4).map((item) => <div key={item.id} className="flex items-center gap-3 px-5 py-3"><div className="min-w-0 flex-1"><p className="truncate text-sm font-medium text-slate-700">{item.subject}</p><p className="text-xs text-slate-400">{item.status === "sent" ? "Sent in MVP" : "Draft"}</p></div>{item.status !== "sent" ? <Button size="sm" variant="outline" disabled={markSent.isPending} onClick={() => markSent.mutate({ id: item.id })}>Mark sent</Button> : <Badge className="bg-emerald-50 text-emerald-700 hover:bg-emerald-50">Sent</Badge>}</div>)}</div> : null}</Panel></>;
}

function StoreSettings({ appearance = false }: { appearance?: boolean }) { const creator = trpc.creator.mine.useQuery(); const update = trpc.creator.update.useMutation({ onSuccess: () => { toast.success("Store saved"); creator.refetch(); } }); const [displayName, setDisplayName] = useState(""); const [bio, setBio] = useState(""); const [handle, setHandle] = useState(""); const [published, setPublished] = useState(false); const [accentColor, setAccentColor] = useState("#1d4ed8"); const current = creator.data; useEffect(() => { if (current) { setDisplayName(current.displayName); setBio(current.bio || ""); setHandle(current.handle); setPublished(current.isPublished); setAccentColor(current.accentColor); } }, [current?.id]); return <><PageHeading eyebrow="My store" title={appearance ? "Appearance" : "Storefront"} description={appearance ? "Choose a restrained, professional visual direction that feels like your own brand." : "Shape the essential profile customers see before they decide to follow, buy, or book."} action={current?.isPublished ? <Button variant="outline" onClick={() => window.open(`/c/${current.handle}`, "_blank")}>View live store<ExternalLink className="ml-2 h-4 w-4" /></Button> : undefined} /><div className="grid gap-6 xl:grid-cols-[minmax(0,1fr)_320px]"><Panel className="p-5 md:p-6"><div className="grid gap-4 md:grid-cols-2"><div className="space-y-2"><Label>Creator name</Label><Input className={fieldClass} value={displayName} onChange={(e) => setDisplayName(e.target.value)} placeholder="Your creator name" /></div><div className="space-y-2"><Label>Store URL</Label><div className="flex rounded-md border border-slate-200 bg-white"><span className="flex items-center border-r border-slate-100 px-3 text-xs text-slate-400">/c/</span><Input className="border-0 bg-transparent focus-visible:ring-0" value={handle} onChange={(e) => setHandle(e.target.value.toLowerCase().replace(/[^a-z0-9-]/g, ""))} placeholder="your-name" /></div></div><div className="space-y-2 md:col-span-2"><Label>Short bio</Label><Textarea className="min-h-28 border-slate-200 bg-white focus-visible:ring-slate-950" value={bio} onChange={(e) => setBio(e.target.value)} placeholder="A concise introduction to your work." /></div>{appearance ? <div className="space-y-2"><Label>Accent color</Label><div className="flex items-center gap-3"><input type="color" value={accentColor} onChange={(event) => setAccentColor(event.target.value)} className="h-10 w-12 rounded border border-slate-200" /><p className="text-xs text-slate-400">Use one calm, recognizable accent.</p></div></div> : null}</div><div className="mt-6 flex items-center justify-between rounded-xl border border-slate-100 bg-slate-50 px-4 py-3"><div><p className="text-sm font-medium text-slate-800">Publish storefront</p><p className="mt-0.5 text-xs text-slate-400">Make your profile and published offers available to visitors.</p></div><Switch checked={published} onCheckedChange={setPublished} /></div><div className="mt-5 flex justify-end"><Button disabled={!displayName || !handle || update.isPending} className="bg-slate-950 text-white" onClick={() => update.mutate({ displayName, bio, handle, theme: current?.theme || "minimal", accentColor, isPublished: published })}>{update.isPending ? "Saving…" : "Save changes"}</Button></div></Panel><Panel className="p-5"><p className="text-xs font-semibold uppercase tracking-[.12em] text-slate-400">Your public link</p><p className="mt-3 break-all text-sm font-medium text-slate-800">{`${window.location.origin}/c/${handle || current?.handle || "your-name"}`}</p><button className="mt-4 flex items-center text-xs font-medium text-slate-700 hover:text-slate-950" onClick={() => { navigator.clipboard.writeText(`${window.location.origin}/c/${handle || current?.handle || ""}`); toast.success("Store link copied"); }}><Copy className="mr-2 h-3.5 w-3.5" />Copy link</button><div className="mt-8 rounded-xl bg-slate-950 p-4 text-white"><p className="text-sm font-medium">A focused storefront converts better.</p><p className="mt-2 text-xs leading-5 text-slate-300">Keep your headline useful, lead with one primary offer, and give visitors a clear next step.</p></div></Panel></div></> }

function Analytics() { const metrics = trpc.dashboard.overview.useQuery(); return <><PageHeading eyebrow="Measure" title="Analytics" description="Track the signals that matter: what your audience buys, how your list grows, and which offers earn attention." /><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><Metric label="Revenue" value={money.format(metrics.data?.revenue ?? 0)} note="Paid order volume" /><Metric label="Recurring" value={money.format(metrics.data?.mrr ?? 0)} note="Monthly recurring revenue" /><Metric label="Subscribers" value={`${metrics.data?.activeSubscribers ?? 0}`} note="Active membership accounts" /><Metric label="Conversion" value={`${metrics.data?.conversionRate ?? 0}%`} note="Customer to buyer ratio" /></div><Panel className="mt-6"><EmptyState icon={<ArrowUpRight className="h-5 w-5" />} title="Analytics will deepen as visitors arrive" description="CreaDock keeps storefront activity, checkout conversion, and offer performance in one clean reporting view." /></Panel></> }

function Checkout() { const creator = trpc.creator.mine.useQuery(); if (creator.error) return <ErrorState title="Checkout workspace unavailable" description="We could not retrieve your creator storefront details right now." />; return <><PageHeading eyebrow="Commerce" title="MVP checkout" description="CreaDock’s MVP checkout lets you test complete buyer flows from the public storefront without connecting a payment provider." /><Panel className="p-6"><div className="flex flex-col gap-5 md:flex-row md:items-start md:justify-between"><div><span className="grid h-10 w-10 place-items-center rounded-xl bg-slate-100"><CreditCard className="h-5 w-5 text-slate-600" /></span><h2 className="mt-4 text-lg font-semibold tracking-[-.04em] text-slate-950">Interactive buyer flow is active</h2><p className="mt-2 max-w-xl text-sm leading-6 text-slate-500">Published products and membership plans can be completed as in-app MVP orders. CreaDock creates the customer, paid order, entitlement, and dashboard update without charging a card.</p></div>{creator.data ? <Button variant="outline" onClick={() => window.open(`/c/${creator.data.handle}`, "_blank")}>Open public store<ExternalLink className="ml-2 h-4 w-4" /></Button> : null}</div><div className="mt-7 grid gap-3 border-t border-slate-100 pt-6 sm:grid-cols-3">{["Paid MVP order record", "Recurring member access", "Digital delivery link"].map((item) => <div className="flex items-center gap-2 text-sm text-slate-600" key={item}><Check className="h-4 w-4 text-emerald-600" />{item}</div>)}</div></Panel></> }

function Help() { return <><PageHeading title="Help center" description="Find the next best step for your storefront, offers, audience, and payments." /><Panel className="divide-y divide-slate-100">{["Set up your first offer", "Publish your creator storefront", "Connect payments", "Invite a teammate"].map((item) => <button key={item} className="flex w-full items-center justify-between px-5 py-4 text-left text-sm font-medium text-slate-700 hover:bg-slate-50"><span>{item}</span><ChevronRight className="h-4 w-4 text-slate-400" /></button>)}</Panel></> }

function WorkspaceContent({ section }: { section: string }) {
  const { user, loading } = useAuth();
  if (loading) return <div className="min-h-screen bg-[#f7f7f3]" />;
  if (!user) return null;
  return { dashboard: <Overview />, products: <Products />, courses: <Courses />, bookings: <Bookings />, memberships: <Memberships />, customers: <Customers />, email: <Email />, store: <StorefrontBuilder />, appearance: <StorefrontBuilder />, pages: <PagesWorkspace />, links: <LinksWorkspace />, media: <MediaLibrary />, analytics: <Analytics />, checkout: <Checkout />, settings: <StoreSettings />, help: <Help /> }[section] || <Overview />;
}

export default function CreatorDashboard() {
  const [location] = useLocation();
  const section = location.split("/")[2] || "dashboard";
  return <DashboardLayout><WorkspaceContent section={section} /></DashboardLayout>;
}
